  1→// Binary entire-agent-test implements the external agent protocol as a minimal
  2→// reference example. It declares no optional capabilities, making it useful for
  3→// testing the base external-agent integration path.
  4→package main
  5→
  6→import (
  7→	"encoding/json"
  8→	"flag"
  9→	"fmt"
 10→	"io"
 11→	"os"
 12→	"path/filepath"
 13→)
 14→
 15→func main() {
 16→	if len(os.Args) < 2 {
 17→		fatal("usage: entire-agent-test <subcommand> [args...]")
 18→	}
 19→
 20→	var err error
 21→	switch os.Args[1] {
 22→	case "info":
 23→		err = cmdInfo()
 24→	case "detect":
 25→		err = cmdDetect()
 26→	case "get-session-id":
 27→		err = cmdGetSessionID()
 28→	case "get-session-dir":
 29→		err = runGetSessionDir()
 30→	case "resolve-session-file":
 31→		err = runResolveSessionFile()
 32→	case "read-session":
 33→		err = cmdReadSession()
 34→	case "write-session":
 35→		err = cmdWriteSession()
 36→	case "format-resume-command":
 37→		err = runFormatResumeCommand()
 38→	case "read-transcript":
 39→		err = runReadTranscript()
 40→	case "chunk-transcript":
 41→		err = runChunkTranscript()
 42→	case "reassemble-transcript":
 43→		err = cmdReassembleTranscript()
 44→	default:
 45→		fatal("unknown subcommand: " + os.Args[1])
 46→	}
 47→
 48→	if err != nil {
 49→		fatal(err.Error())
 50→	}
 51→}
 52→
 53→// ---------------------------------------------------------------------------
 54→// Subcommand implementations
 55→// ---------------------------------------------------------------------------
 56→
 57→func cmdInfo() error {
 58→	return writeJSON(map[string]interface{}{
 59→		"protocol_version": 1,
 60→		"name":             "test-agent",
 61→		"type":             "Test Agent",
 62→		"description":      "Minimal reference implementation of the external agent protocol",
 63→		"is_preview":       true,
 64→		"protected_dirs":   []string{".test-agent"},
 65→		"hook_names":       []string{},
 66→		"capabilities": map[string]bool{
 67→			"hooks":                    false,
 68→			"transcript_analyzer":      false,
 69→			"transcript_preparer":      false,
 70→			"token_calculator":         false,
 71→			"text_generator":           false,
 72→			"hook_response_writer":     false,
 73→			"subagent_aware_extractor": false,
 74→		},
 75→	})
 76→}
 77→
 78→func cmdDetect() error {
 79→	return writeJSON(map[string]interface{}{
 80→		"present": true,
 81→	})
 82→}
 83→
 84→func cmdGetSessionID() error {
 85→	input, err := io.ReadAll(os.Stdin)
 86→	if err != nil {
 87→		return fmt.Errorf("failed to read stdin: %w", err)
 88→	}
 89→	var hookInput struct {
 90→		SessionID string `json:"session_id"`
 91→	}
 92→	if err := json.Unmarshal(input, &hookInput); err != nil {
 93→		return fmt.Errorf("failed to unmarshal hook input: %w", err)
 94→	}
 95→	return writeJSON(map[string]interface{}{
 96→		"session_id": hookInput.SessionID,
 97→	})
 98→}
 99→
100→func runGetSessionDir() error {
101→	fs := flag.NewFlagSet("get-session-dir", flag.ContinueOnError)
102→	repoPath := fs.String("repo-path", "", "repository path")
103→	if err := fs.Parse(os.Args[2:]); err != nil {
104→		return fmt.Errorf("failed to parse flags: %w", err)
105→	}
106→	return writeJSON(map[string]interface{}{
107→		"session_dir": filepath.Join(*repoPath, ".test-agent", "sessions"),
108→	})
109→}
110→
111→func runResolveSessionFile() error {
112→	fs := flag.NewFlagSet("resolve-session-file", flag.ContinueOnError)
113→	sessionDir := fs.String("session-dir", "", "session directory")
114→	sessionID := fs.String("session-id", "", "session ID")
115→	if err := fs.Parse(os.Args[2:]); err != nil {
116→		return fmt.Errorf("failed to parse flags: %w", err)
117→	}
118→	return writeJSON(map[string]interface{}{
119→		"session_file": filepath.Join(*sessionDir, *sessionID+".jsonl"),
120→	})
121→}
122→
123→func cmdReadSession() error {
124→	// Read and discard stdin (HookInput JSON).
125→	if _, err := io.ReadAll(os.Stdin); err != nil {
126→		return fmt.Errorf("failed to read stdin: %w", err)
127→	}
128→	// Return a minimal AgentSession stub.
129→	return writeJSON(map[string]interface{}{
130→		"session_id":     "",
131→		"agent_name":     "test-agent",
132→		"repo_path":      "",
133→		"session_ref":    "",
134→		"start_time":     "",
135→		"native_data":    nil,
136→		"modified_files": []string{},
137→		"new_files":      []string{},
138→		"deleted_files":  []string{},
139→	})
140→}
141→
142→func cmdWriteSession() error {
143→	// Read and discard stdin (AgentSession JSON). No-op.
144→	if _, err := io.ReadAll(os.Stdin); err != nil {
145→		return fmt.Errorf("failed to read stdin: %w", err)
146→	}
147→	return nil
148→}
149→
150→func runFormatResumeCommand() error {
151→	fs := flag.NewFlagSet("format-resume-command", flag.ContinueOnError)
152→	sessionID := fs.String("session-id", "", "session ID")
153→	if err := fs.Parse(os.Args[2:]); err != nil {
154→		return fmt.Errorf("failed to parse flags: %w", err)
155→	}
156→	return writeJSON(map[string]interface{}{
157→		"command": "test-agent resume " + *sessionID,
158→	})
159→}
160→
161→func runReadTranscript() error {
162→	fs := flag.NewFlagSet("read-transcript", flag.ContinueOnError)
163→	sessionRef := fs.String("session-ref", "", "session reference path")
164→	if err := fs.Parse(os.Args[2:]); err != nil {
165→		return fmt.Errorf("failed to parse flags: %w", err)
166→	}
167→	data, err := os.ReadFile(*sessionRef)
168→	if err != nil {
169→		return fmt.Errorf("failed to read transcript: %w", err)
170→	}
171→	if _, err := os.Stdout.Write(data); err != nil {
172→		return fmt.Errorf("failed to write output: %w", err)
173→	}
174→	return nil
175→}
176→
177→func runChunkTranscript() error {
178→	fs := flag.NewFlagSet("chunk-transcript", flag.ContinueOnError)
179→	maxSize := fs.Int("max-size", 0, "maximum chunk size in bytes")
180→	if err := fs.Parse(os.Args[2:]); err != nil {
181→		return fmt.Errorf("failed to parse flags: %w", err)
182→	}
183→
184→	content, err := io.ReadAll(os.Stdin)
185→	if err != nil {
186→		return fmt.Errorf("failed to read stdin: %w", err)
187→	}
188→
189→	chunkSize := *maxSize
190→	if chunkSize <= 0 {
191→		chunkSize = len(content)
192→	}
193→
194→	// json.Marshal automatically base64-encodes []byte elements.
195→	var chunks [][]byte
196→	for i := 0; i < len(content); i += chunkSize {
197→		end := i + chunkSize
198→		if end > len(content) {
199→			end = len(content)
200→		}
201→		chunks = append(chunks, content[i:end])
202→	}
203→
204→	return writeJSON(map[string]interface{}{
205→		"chunks": chunks,
206→	})
207→}
208→
209→func cmdReassembleTranscript() error {
210→	input, err := io.ReadAll(os.Stdin)
211→	if err != nil {
212→		return fmt.Errorf("failed to read stdin: %w", err)
213→	}
214→
215→	var resp struct {
216→		Chunks [][]byte `json:"chunks"`
217→	}
218→	if err := json.Unmarshal(input, &resp); err != nil {
219→		return fmt.Errorf("failed to unmarshal chunks: %w", err)
220→	}
221→
222→	// json.Unmarshal automatically base64-decodes []byte elements.
223→	for _, chunk := range resp.Chunks {
224→		if _, err := os.Stdout.Write(chunk); err != nil {
225→			return fmt.Errorf("failed to write output: %w", err)
226→		}
227→	}
228→	return nil
229→}
230→
231→// ---------------------------------------------------------------------------
232→// Helpers
233→// ---------------------------------------------------------------------------
234→
235→func writeJSON(v interface{}) error {
236→	data, err := json.Marshal(v)
237→	if err != nil {
238→		return fmt.Errorf("failed to marshal JSON: %w", err)
239→	}
240→	if _, err := os.Stdout.Write(data); err != nil {
241→		return fmt.Errorf("failed to write output: %w", err)
242→	}
243→	return nil
244→}
245→
246→func fatal(msg string) {
247→	fmt.Fprintln(os.Stderr, msg)
248→	os.Exit(1)
249→}
