  1→// Package cursor implements the Agent interface for Cursor.
  2→package cursor
  3→
  4→import (
  5→	"context"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"path/filepath"
 10→	"regexp"
 11→	"strings"
 12→	"time"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/agent"
 15→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 20→func init() {
 21→	agent.Register(agent.AgentNameCursor, NewCursorAgent)
 22→}
 23→
 24→// CursorAgent implements the Agent interface for Cursor.
 25→//
 26→//nolint:revive // CursorAgent is clearer than Agent in this context
 27→type CursorAgent struct{}
 28→
 29→// NewCursorAgent creates a new Cursor agent instance.
 30→func NewCursorAgent() agent.Agent {
 31→	return &CursorAgent{}
 32→}
 33→
 34→// Name returns the agent registry key.
 35→func (c *CursorAgent) Name() types.AgentName {
 36→	return agent.AgentNameCursor
 37→}
 38→
 39→// Type returns the agent type identifier.
 40→func (c *CursorAgent) Type() types.AgentType {
 41→	return agent.AgentTypeCursor
 42→}
 43→
 44→// Description returns a human-readable description.
 45→func (c *CursorAgent) Description() string {
 46→	return "Cursor - AI-powered code editor"
 47→}
 48→
 49→func (c *CursorAgent) IsPreview() bool { return true }
 50→
 51→// DetectPresence checks if Cursor is configured in the repository.
 52→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 53→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 54→	if err != nil {
 55→		worktreeRoot = "."
 56→	}
 57→
 58→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 59→	if _, err := os.Stat(cursorDir); err == nil {
 60→		return true, nil
 61→	}
 62→	return false, nil
 63→}
 64→
 65→// GetSessionID extracts the session ID from hook input.
 66→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 67→	return input.SessionID
 68→}
 69→
 70→// ResolveSessionFile returns the path to a Cursor session file.
 71→// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
 72→// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
 73→// We prefer nested if the file OR directory exists (the directory may be created
 74→// before the file is flushed), otherwise fall back to flat.
 75→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 76→	nestedDir := filepath.Join(sessionDir, agentSessionID)
 77→	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
 78→	if _, err := os.Stat(nested); err == nil {
 79→		return nested
 80→	}
 81→	// IDE creates the directory before the transcript file — predict nested path.
 82→	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
 83→		return nested
 84→	}
 85→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 86→}
 87→
 88→// ProtectedDirs returns directories that Cursor uses for config/state.
 89→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 90→
 91→// GetSessionDir returns the directory where Cursor stores session transcripts.
 92→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 93→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 94→		return override, nil
 95→	}
 96→
 97→	homeDir, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return "", fmt.Errorf("failed to get home directory: %w", err)
100→	}
101→
102→	projectDir := sanitizePathForCursor(repoPath)
103→	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
104→}
105→
106→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
107→// Note: ModifiedFiles is left empty because Cursor's transcript does not contain
108→// tool_use blocks for file detection. TranscriptAnalyzer extracts prompts and
109→// summaries; file detection relies on git status.
110→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
111→	if input.SessionRef == "" {
112→		return nil, errors.New("session reference (transcript path) is required")
113→	}
114→
115→	data, err := os.ReadFile(input.SessionRef)
116→	if err != nil {
117→		return nil, fmt.Errorf("failed to read transcript: %w", err)
118→	}
119→
120→	return &agent.AgentSession{
121→		SessionID:  input.SessionID,
122→		AgentName:  c.Name(),
123→		SessionRef: input.SessionRef,
124→		StartTime:  time.Now(),
125→		NativeData: data,
126→	}, nil
127→}
128→
129→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
130→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
131→	if session == nil {
132→		return errors.New("session is nil")
133→	}
134→
135→	if session.AgentName != "" && session.AgentName != c.Name() {
136→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
137→	}
138→
139→	if session.SessionRef == "" {
140→		return errors.New("session reference (transcript path) is required")
141→	}
142→
143→	if len(session.NativeData) == 0 {
144→		return errors.New("session has no native data to write")
145→	}
146→
147→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
148→		return fmt.Errorf("failed to write transcript: %w", err)
149→	}
150→
151→	return nil
152→}
153→
154→// FormatResumeCommand returns an instruction to resume a Cursor session.
155→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
156→func (c *CursorAgent) FormatResumeCommand(_ string) string {
157→	return "Open this project in Cursor to continue the session."
158→}
159→
160→// sanitizePathForCursor converts a path to Cursor's project directory format.
161→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
162→
163→func sanitizePathForCursor(path string) string {
164→	path = strings.TrimLeft(path, "/")
165→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
166→}
167→
168→// ChunkTranscript splits a JSONL transcript at line boundaries.
169→func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
170→	chunks, err := agent.ChunkJSONL(content, maxSize)
171→	if err != nil {
172→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
173→	}
174→	return chunks, nil
175→}
176→
177→// ReassembleTranscript concatenates JSONL chunks with newlines.
178→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
179→	return agent.ReassembleJSONL(chunks), nil
180→}
181→

  1→package cursor
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"os"
  8→	"path/filepath"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→)
 15→
 16→// Ensure CursorAgent implements HookSupport
 17→var (
 18→	_ agent.HookSupport = (*CursorAgent)(nil)
 19→)
 20→
 21→// Cursor hook names - these become subcommands under `entire hooks cursor`
 22→const (
 23→	HookNameSessionStart       = "session-start"
 24→	HookNameSessionEnd         = "session-end"
 25→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 26→	HookNameStop               = "stop"
 27→	HookNamePreCompact         = "pre-compact"
 28→	HookNameSubagentStart      = "subagent-start"
 29→	HookNameSubagentStop       = "subagent-stop"
 30→)
 31→
 32→// HooksFileName is the hooks file used by Cursor.
 33→const HooksFileName = "hooks.json"
 34→
 35→// entireHookPrefixes are command prefixes that identify Entire hooks
 36→var entireHookPrefixes = []string{
 37→	"entire ",
 38→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
 39→}
 40→
 41→// HookNames returns the hook verbs Cursor supports.
 42→// These become subcommands: entire hooks cursor <verb>
 43→func (c *CursorAgent) HookNames() []string {
 44→	return []string{
 45→		HookNameSessionStart,
 46→		HookNameSessionEnd,
 47→		HookNameBeforeSubmitPrompt,
 48→		HookNameStop,
 49→		HookNamePreCompact,
 50→		HookNameSubagentStart,
 51→		HookNameSubagentStop,
 52→	}
 53→}
 54→
 55→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 56→// If force is true, removes existing Entire hooks before installing.
 57→// Returns the number of hooks installed.
 58→// Unknown top-level fields and hook types are preserved on round-trip.
 59→func (c *CursorAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 60→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 61→	if err != nil {
 62→		worktreeRoot = "."
 63→	}
 64→
 65→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
 66→
 67→	// Use raw maps to preserve unknown fields on round-trip
 68→	var rawFile map[string]json.RawMessage
 69→	var rawHooks map[string]json.RawMessage
 70→
 71→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 72→	if readErr == nil {
 73→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 74→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 75→		}
 76→		if hooksRaw, ok := rawFile["hooks"]; ok {
 77→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 78→				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 79→			}
 80→		}
 81→		if _, ok := rawFile["version"]; !ok {
 82→			rawFile["version"] = json.RawMessage(`1`)
 83→		}
 84→	} else {
 85→		rawFile = map[string]json.RawMessage{
 86→			"version": json.RawMessage(`1`),
 87→		}
 88→	}
 89→
 90→	if rawHooks == nil {
 91→		rawHooks = make(map[string]json.RawMessage)
 92→	}
 93→
 94→	// Parse only the hook types we manage
 95→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
 96→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 97→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 98→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 99→	parseCursorHookType(rawHooks, "stop", &stop)
100→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
101→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
102→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
103→
104→	// If force is true, remove all existing Entire hooks first
105→	if force {
106→		sessionStart = removeEntireHooks(sessionStart)
107→		sessionEnd = removeEntireHooks(sessionEnd)
108→		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
109→		stop = removeEntireHooks(stop)
110→		preCompact = removeEntireHooks(preCompact)
111→		subagentStart = removeEntireHooks(subagentStart)
112→		subagentStop = removeEntireHooks(subagentStop)
113→	}
114→
115→	// Define hook commands
116→	var cmdPrefix string
117→	if localDev {
118→		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
119→	} else {
120→		cmdPrefix = "entire hooks cursor "
121→	}
122→
123→	sessionStartCmd := cmdPrefix + HookNameSessionStart
124→	sessionEndCmd := cmdPrefix + HookNameSessionEnd
125→	beforeSubmitPromptCmd := cmdPrefix + HookNameBeforeSubmitPrompt
126→	stopCmd := cmdPrefix + HookNameStop
127→	preCompactCmd := cmdPrefix + HookNamePreCompact
128→	subagentStartCmd := cmdPrefix + HookNameSubagentStart
129→	subagentEndCmd := cmdPrefix + HookNameSubagentStop
130→
131→	count := 0
132→
133→	// Add hooks if they don't exist
134→	if !hookCommandExists(sessionStart, sessionStartCmd) {
135→		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
136→		count++
137→	}
138→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
139→		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
140→		count++
141→	}
142→	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
143→		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
144→		count++
145→	}
146→	if !hookCommandExists(stop, stopCmd) {
147→		stop = append(stop, CursorHookEntry{Command: stopCmd})
148→		count++
149→	}
150→	if !hookCommandExists(preCompact, preCompactCmd) {
151→		preCompact = append(preCompact, CursorHookEntry{Command: preCompactCmd})
152→		count++
153→	}
154→	if !hookCommandExists(subagentStart, subagentStartCmd) {
155→		subagentStart = append(subagentStart, CursorHookEntry{Command: subagentStartCmd})
156→		count++
157→	}
158→	if !hookCommandExists(subagentStop, subagentEndCmd) {
159→		subagentStop = append(subagentStop, CursorHookEntry{Command: subagentEndCmd})
160→		count++
161→	}
162→
163→	if count == 0 {
164→		return 0, nil
165→	}
166→
167→	// Marshal modified hook types back into rawHooks
168→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
169→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
170→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
171→	marshalCursorHookType(rawHooks, "stop", stop)
172→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
173→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
174→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
175→
176→	// Marshal hooks and update raw file
177→	hooksJSON, err := json.Marshal(rawHooks)
178→	if err != nil {
179→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
180→	}
181→	rawFile["hooks"] = hooksJSON
182→
183→	// Write to file
184→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
185→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
186→	}
187→
188→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
189→	if err != nil {
190→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
191→	}
192→
193→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
194→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
195→	}
196→
197→	return count, nil
198→}
199→
200→// UninstallHooks removes Entire hooks from Cursor HooksFileName.
201→// Unknown top-level fields and hook types are preserved on round-trip.
202→func (c *CursorAgent) UninstallHooks(ctx context.Context) error {
203→	worktreeRoot, err := paths.WorktreeRoot(ctx)
204→	if err != nil {
205→		worktreeRoot = "."
206→	}
207→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
208→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
209→	if err != nil {
210→		return nil //nolint:nilerr // No hooks file means nothing to uninstall
211→	}
212→
213→	var rawFile map[string]json.RawMessage
214→	if err := json.Unmarshal(data, &rawFile); err != nil {
215→		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
216→	}
217→
218→	var rawHooks map[string]json.RawMessage
219→	if hooksRaw, ok := rawFile["hooks"]; ok {
220→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
221→			return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
222→		}
223→	}
224→	if rawHooks == nil {
225→		rawHooks = make(map[string]json.RawMessage)
226→	}
227→
228→	// Parse only the hook types we manage
229→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
230→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
231→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
232→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
233→	parseCursorHookType(rawHooks, "stop", &stop)
234→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
235→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
236→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
237→
238→	// Remove Entire hooks from all hook types
239→	sessionStart = removeEntireHooks(sessionStart)
240→	sessionEnd = removeEntireHooks(sessionEnd)
241→	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
242→	stop = removeEntireHooks(stop)
243→	preCompact = removeEntireHooks(preCompact)
244→	subagentStart = removeEntireHooks(subagentStart)
245→	subagentStop = removeEntireHooks(subagentStop)
246→
247→	// Marshal modified hook types back into rawHooks
248→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
249→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
250→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
251→	marshalCursorHookType(rawHooks, "stop", stop)
252→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
253→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
254→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
255→
256→	// Marshal hooks back (preserving unknown hook types)
257→	if len(rawHooks) > 0 {
258→		hooksJSON, err := json.Marshal(rawHooks)
259→		if err != nil {
260→			return fmt.Errorf("failed to marshal hooks: %w", err)
261→		}
262→		rawFile["hooks"] = hooksJSON
263→	} else {
264→		delete(rawFile, "hooks")
265→	}
266→
267→	// Write back
268→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
269→	if err != nil {
270→		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
271→	}
272→
273→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
274→		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
275→	}
276→	return nil
277→}
278→
279→// AreHooksInstalled checks if Entire hooks are installed.
280→func (c *CursorAgent) AreHooksInstalled(ctx context.Context) bool {
281→	worktreeRoot, err := paths.WorktreeRoot(ctx)
282→	if err != nil {
283→		worktreeRoot = "."
284→	}
285→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
286→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
287→	if err != nil {
288→		return false
289→	}
290→
291→	var hooksFile CursorHooksFile
292→	if err := json.Unmarshal(data, &hooksFile); err != nil {
293→		return false
294→	}
295→
296→	return hasEntireHook(hooksFile.Hooks.SessionStart) ||
297→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
298→		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
299→		hasEntireHook(hooksFile.Hooks.Stop) ||
300→		hasEntireHook(hooksFile.Hooks.PreCompact) ||
301→		hasEntireHook(hooksFile.Hooks.SubagentStart) ||
302→		hasEntireHook(hooksFile.Hooks.SubagentStop)
303→}
