 15→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 16→// Returns nil if the hook has no lifecycle significance.
 17→func (c *CursorAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 18→	switch hookName {
 19→	case HookNameSessionStart:
 20→		return c.parseSessionStart(stdin)
 21→	case HookNameBeforeSubmitPrompt:
 22→		return c.parseTurnStart(ctx, stdin)
 23→	case HookNameStop:
 24→		return c.parseTurnEnd(ctx, stdin)
 25→	case HookNameSessionEnd:
 26→		return c.parseSessionEnd(ctx, stdin)
 27→	case HookNamePreCompact:
 28→		return c.parsePreCompact(stdin)
 29→	case HookNameSubagentStart:
 30→		return c.parseSubagentStart(stdin)
 31→	case HookNameSubagentStop:
 32→		return c.parseSubagentStop(stdin)
 33→	default:
 34→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 35→	}
 36→}
