 18→// GetTranscriptPosition returns the current line count of a Cursor transcript.
 19→// Cursor uses the same JSONL format as Claude Code, so position is the number of lines.
 20→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
 21→// Returns 0 if the file doesn't exist or is empty.
 22→func (c *CursorAgent) GetTranscriptPosition(path string) (int, error) {
 23→	if path == "" {
 24→		return 0, nil
 25→	}
 26→
 27→	file, err := os.Open(path) //nolint:gosec // Path comes from Cursor transcript location
 28→	if err != nil {
 29→		if os.IsNotExist(err) {
 30→			return 0, nil
 31→		}
 32→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
 33→	}
 34→	defer file.Close()
 35→
 36→	reader := bufio.NewReader(file)
 37→	lineCount := 0
 38→
 39→	for {
 40→		line, err := reader.ReadBytes('\n')
 41→		if err != nil {
 42→			if err == io.EOF {
 43→				if len(line) > 0 {
 44→					lineCount++ // Count final line without trailing newline
 45→				}
 46→				break
 47→			}
 48→			return 0, fmt.Errorf("failed to read transcript: %w", err)
 49→		}
 50→		lineCount++
 51→	}
 52→
 53→	return lineCount, nil
 54→}
 55→
 56→// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
 57→// Cursor uses the same JSONL format as Claude Code; the shared transcript package normalizes
 58→// "role" → "type" and strips <user_query> tags.
 59→func (c *CursorAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 60→	lines, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
 61→	if err != nil {
 62→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 63→	}
 64→
 65→	var prompts []string
 66→	for i := range lines {
 67→		if lines[i].Type != transcript.TypeUser {
 68→			continue
 69→		}
 70→		content := transcript.ExtractUserContent(lines[i].Message)
 71→		if content != "" {
 72→			prompts = append(prompts, textutil.StripIDEContextTags(content))
 73→		}
 74→	}
 75→	return prompts, nil
 76→}
 77→
 78→// ExtractSummary extracts the last assistant message as a session summary.
 79→func (c *CursorAgent) ExtractSummary(sessionRef string) (string, error) {
 80→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 81→	if err != nil {
 82→		return "", fmt.Errorf("failed to read transcript: %w", err)
 83→	}
 84→
 85→	lines, parseErr := transcript.ParseFromBytes(data)
 86→	if parseErr != nil {
 87→		return "", fmt.Errorf("failed to parse transcript: %w", parseErr)
 88→	}
 89→
 90→	// Walk backward to find last assistant text block
 91→	for i := len(lines) - 1; i >= 0; i-- {
 92→		if lines[i].Type != transcript.TypeAssistant {
 93→			continue
 94→		}
 95→		var msg transcript.AssistantMessage
 96→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
 97→			continue
 98→		}
 99→		for _, block := range msg.Content {
100→			if block.Type == transcript.ContentTypeText && block.Text != "" {
101→				return block.Text, nil
102→			}
103→		}
104→	}
105→	return "", nil
106→}
