 19→// Agent implements agent.Agent by delegating to an external binary.
 20→// Each method invokes a subcommand on the binary and parses the JSON response.
 21→type Agent struct {
 22→	binaryPath string
 23→	info       *InfoResponse
 24→}
 25→
 26→// New creates an Agent by calling the binary's "info" subcommand
 27→// to cache its metadata. Returns an error if the binary cannot be invoked or returns
 28→// invalid/incompatible protocol data.
 29→func New(binaryPath string) (*Agent, error) {
 30→	ea := &Agent{binaryPath: binaryPath}
 31→
 32→	stdout, err := ea.run(context.Background(), nil, "info")
 33→	if err != nil {
 34→		return nil, fmt.Errorf("info: %w", err)
 35→	}
 36→
 37→	var info InfoResponse
 38→	if err := json.Unmarshal(stdout, &info); err != nil {
 39→		return nil, fmt.Errorf("info: invalid JSON: %w", err)
 40→	}
 41→
 42→	if info.ProtocolVersion != ProtocolVersion {
 43→		return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
 44→			info.ProtocolVersion, ProtocolVersion)
 45→	}
 46→
 47→	ea.info = &info
 48→	return ea, nil
 49→}
 50→
 51→// Info returns the cached info response.
 52→func (e *Agent) Info() *InfoResponse {
 53→	return e.info
 54→}
