393→// run executes a subcommand on the external binary and returns stdout bytes.
394→// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
395→// included in the returned error.
396→func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
397→	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
398→
399→	// Set environment: repo root + protocol version
400→	cmd.Env = append(cmd.Environ(),
401→		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
402→	)
403→	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
404→		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
405→		cmd.Dir = repoRoot
406→	}
407→
408→	if stdin != nil {
409→		cmd.Stdin = bytes.NewReader(stdin)
410→	}
411→
412→	var stdoutBuf, stderrBuf bytes.Buffer
413→	cmd.Stdout = &stdoutBuf
414→	cmd.Stderr = &stderrBuf
415→
416→	if err := cmd.Run(); err != nil {
417→		errMsg := strings.TrimSpace(stderrBuf.String())
418→		if errMsg != "" {
419→			return nil, fmt.Errorf("%s: %s", args[0], errMsg)
420→		}
421→		return nil, fmt.Errorf("%s: %w", args[0], err)
422→	}
423→
424→	return stdoutBuf.Bytes(), nil
425→}
