// Binary entire-agent-cursor implements the external agent protocol for Cursor.
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// writeJSON marshals v as JSON and writes it to stdout.
func writeJSON(v any) error {
	data, err := json.Marshal(v)
	if err != nil {
		return fmt.Errorf("failed to marshal JSON: %w", err)
	}
	if _, err := os.Stdout.Write(data); err != nil {
		return fmt.Errorf("failed to write output: %w", err)
	}
	return nil
}

// fatal prints msg to stderr and exits 1.
func fatal(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	os.Exit(1)
}

// repoRoot returns the repository root. It first checks the ENTIRE_REPO_ROOT
// env var (set by the CLI), then falls back to git rev-parse.
func repoRoot() (string, error) {
	if root := os.Getenv("ENTIRE_REPO_ROOT"); root != "" {
		return root, nil
	}
	cmd := exec.Command("git", "rev-parse", "--show-toplevel")
	out, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get repo root: %w", err)
	}
	return strings.TrimSpace(string(out)), nil
}

// marshalIndentWithNewline is like json.MarshalIndent but adds a trailing newline.
func marshalIndentWithNewline(v any, prefix, indent string) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent(prefix, indent)
	if err := enc.Encode(v); err != nil {
		return nil, fmt.Errorf("encoding JSON: %w", err)
	}
	return buf.Bytes(), nil
}

// chunkJSONL splits JSONL content at line boundaries.
func chunkJSONL(content []byte, maxSize int) ([][]byte, error) {
	if len(content) == 0 {
		return [][]byte{}, nil
	}

	lines := strings.Split(string(content), "\n")
	var chunks [][]byte
	var currentChunk strings.Builder

	for i, line := range lines {
		lineWithNewline := line + "\n"

		if len(lineWithNewline) > maxSize {
			return nil, fmt.Errorf("JSONL line %d exceeds maximum chunk size (%d bytes > %d bytes)", i+1, len(lineWithNewline), maxSize)
		}

		if currentChunk.Len()+len(lineWithNewline) > maxSize && currentChunk.Len() > 0 {
			chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
			currentChunk.Reset()
		}
		currentChunk.WriteString(lineWithNewline)
	}

	if currentChunk.Len() > 0 {
		chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
	}

	return chunks, nil
}

// reassembleJSONL concatenates JSONL chunks with newlines.
func reassembleJSONL(chunks [][]byte) []byte {
	var result strings.Builder
	for i, chunk := range chunks {
		result.Write(chunk)
		if i < len(chunks)-1 {
			result.WriteString("\n")
		}
	}
	return []byte(result.String())
}

// readJSON reads all stdin and unmarshals JSON into the given type.
func readJSON[T any]() (*T, error) {
	data, err := readStdin()
	if err != nil {
		return nil, err
	}
	if len(data) == 0 {
		return nil, fmt.Errorf("empty hook input")
	}
	var result T
	if err := json.Unmarshal(data, &result); err != nil {
		return nil, fmt.Errorf("failed to parse hook input: %w", err)
	}
	return &result, nil
}

// readStdin reads all bytes from stdin.
func readStdin() ([]byte, error) {
	data, err := os.ReadFile("/dev/stdin")
	if err != nil {
		return nil, fmt.Errorf("failed to read stdin: %w", err)
	}
	return data, nil
}

// stripIDEContextTags removes IDE-injected context tags from prompt text.
func stripIDEContextTags(text string) string {
	result := ideContextTagRegex.ReplaceAllString(text, "")
	for _, re := range systemTagRegexes {
		result = re.ReplaceAllString(result, "")
	}
	return strings.TrimSpace(result)
}

package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
)

// Transcript type constants.
const (
	typeUser      = "user"
	typeAssistant = "assistant"
	contentTypeText = "text"
)

// line represents a single line in a Cursor JSONL transcript.
type line struct {
	Type    string          `json:"type"`
	Role    string          `json:"role,omitempty"`
	UUID    string          `json:"uuid"`
	Message json.RawMessage `json:"message"`
}

// userMessage represents a user message in the transcript.
type userMessage struct {
	Content any `json:"content"`
}

// assistantMessage represents an assistant message in the transcript.
type assistantMessage struct {
	Content []contentBlock `json:"content"`
}

// contentBlock represents a block within an assistant message.
type contentBlock struct {
	Type string `json:"type"`
	Text string `json:"text,omitempty"`
}

// normalizeLineType ensures line.Type is populated.
// Cursor uses "role" while Claude Code uses "type".
func normalizeLineType(l *line) {
	if l.Type == "" && l.Role != "" {
		l.Type = l.Role
	}
}

// parseFromBytes parses transcript content from a byte slice.
func parseFromBytes(content []byte) ([]line, error) {
	var lines []line
	reader := bufio.NewReader(bytes.NewReader(content))

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, fmt.Errorf("failed to read transcript: %w", err)
		}

		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		var l line
		if err := json.Unmarshal(lineBytes, &l); err == nil {
			normalizeLineType(&l)
			lines = append(lines, l)
		}

		if err == io.EOF {
			break
		}
	}

	return lines, nil
}

// parseFromFileAtLine reads and parses a transcript file starting from a specific line.
func parseFromFileAtLine(path string, startLine int) ([]line, error) {
	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
	if err != nil {
		return nil, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer func() { _ = file.Close() }()

	var lines []line
	reader := bufio.NewReader(file)

	totalLines := 0
	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, fmt.Errorf("failed to read transcript: %w", err)
		}

		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		if totalLines >= startLine {
			var l line
			if err := json.Unmarshal(lineBytes, &l); err == nil {
				normalizeLineType(&l)
				lines = append(lines, l)
			}
		}
		totalLines++

		if err == io.EOF {
			break
		}
	}

	return lines, nil
}

// extractUserContent extracts user content from a raw message.
// Handles both string and array content formats.
func extractUserContent(message json.RawMessage) string {
	var msg userMessage
	if err := json.Unmarshal(message, &msg); err != nil {
		return ""
	}

	// Handle string content
	if str, ok := msg.Content.(string); ok {
		return stripIDEContextTags(str)
	}

	// Handle array content
	if arr, ok := msg.Content.([]any); ok {
		var texts []string
		for _, item := range arr {
			if m, ok := item.(map[string]any); ok {
				if m["type"] == contentTypeText {
					if text, ok := m["text"].(string); ok {
						texts = append(texts, text)
					}
				}
			}
		}
		if len(texts) > 0 {
			return stripIDEContextTags(strings.Join(texts, "\n\n"))
		}
	}

	return ""
}

package main

import (
	"os"
	"path/filepath"
)

func cmdInfo() error {
	return writeJSON(map[string]any{
		"protocol_version": 1,
		"name":             "cursor",
		"type":             "Cursor",
		"description":      "Cursor - AI-powered code editor",
		"is_preview":       true,
		"protected_dirs":   []string{".cursor"},
		"hook_names": []string{
			hookNameSessionStart,
			hookNameSessionEnd,
			hookNameBeforeSubmitPrompt,
			hookNameStop,
			hookNamePreCompact,
			hookNameSubagentStart,
			hookNameSubagentStop,
		},
		"capabilities": map[string]bool{
			"hooks":                    true,
			"transcript_analyzer":      true,
			"transcript_preparer":      false,
			"token_calculator":         false,
			"text_generator":           false,
			"hook_response_writer":     false,
			"subagent_aware_extractor": false,
		},
	})
}

func cmdDetect() error {
	root, err := repoRoot()
	if err != nil {
		root = "."
	}

	cursorDir := filepath.Join(root, ".cursor")
	if _, err := os.Stat(cursorDir); err == nil {
		return writeJSON(map[string]any{"present": true})
	}
	return writeJSON(map[string]any{"present": false})
}

package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)

func sanitizePathForCursor(path string) string {
	path = strings.TrimLeft(path, "/")
	return nonAlphanumericRegex.ReplaceAllString(path, "-")
}

func cmdGetSessionID() error {
	var hookInput struct {
		SessionID string `json:"session_id"`
	}
	data, err := readStdin()
	if err != nil {
		return err
	}
	if err := json.Unmarshal(data, &hookInput); err != nil {
		return fmt.Errorf("failed to unmarshal hook input: %w", err)
	}
	return writeJSON(map[string]any{
		"session_id": hookInput.SessionID,
	})
}

func cmdGetSessionDir() error {
	fs := flag.NewFlagSet("get-session-dir", flag.ContinueOnError)
	repoPath := fs.String("repo-path", "", "repository path")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return fmt.Errorf("failed to parse flags: %w", err)
	}

	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
		return writeJSON(map[string]any{"session_dir": override})
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("failed to get home directory: %w", err)
	}

	projectDir := sanitizePathForCursor(*repoPath)
	sessionDir := filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts")
	return writeJSON(map[string]any{"session_dir": sessionDir})
}

func cmdResolveSessionFile() error {
	fs := flag.NewFlagSet("resolve-session-file", flag.ContinueOnError)
	sessionDir := fs.String("session-dir", "", "session directory")
	sessionID := fs.String("session-id", "", "session ID")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return fmt.Errorf("failed to parse flags: %w", err)
	}

	result := resolveSessionFile(*sessionDir, *sessionID)
	return writeJSON(map[string]any{"session_file": result})
}

// resolveSessionFile returns the path to a Cursor session file.
// Cursor IDE uses nested layout: <dir>/<id>/<id>.jsonl
// Cursor CLI uses flat layout: <dir>/<id>.jsonl
// Prefers nested if file OR directory exists.
func resolveSessionFile(sessionDir, agentSessionID string) string {
	nestedDir := filepath.Join(sessionDir, agentSessionID)
	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
	if _, err := os.Stat(nested); err == nil {
		return nested
	}
	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
		return nested
	}
	return filepath.Join(sessionDir, agentSessionID+".jsonl")
}

func cmdReadSession() error {
	data, err := readStdin()
	if err != nil {
		return err
	}

	var hookInput struct {
		SessionID  string `json:"session_id"`
		SessionRef string `json:"session_ref"`
	}
	if err := json.Unmarshal(data, &hookInput); err != nil {
		return fmt.Errorf("failed to parse hook input: %w", err)
	}

	if hookInput.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	transcriptData, err := os.ReadFile(hookInput.SessionRef) //nolint:gosec // path from hook input
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}

	return writeJSON(map[string]any{
		"session_id":     hookInput.SessionID,
		"agent_name":     "cursor",
		"repo_path":      "",
		"session_ref":    hookInput.SessionRef,
		"start_time":     time.Now().Format(time.RFC3339),
		"native_data":    transcriptData,
		"modified_files": []string{},
		"new_files":      []string{},
		"deleted_files":  []string{},
	})
}

func cmdWriteSession() error {
	data, err := readStdin()
	if err != nil {
		return err
	}

	var session struct {
		AgentName  string `json:"agent_name"`
		SessionRef string `json:"session_ref"`
		NativeData []byte `json:"native_data"`
	}
	if err := json.Unmarshal(data, &session); err != nil {
		return fmt.Errorf("failed to parse session: %w", err)
	}

	if session.AgentName != "" && session.AgentName != "cursor" {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, "cursor")
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

func cmdFormatResumeCommand() error {
	fs := flag.NewFlagSet("format-resume-command", flag.ContinueOnError)
	_ = fs.String("session-id", "", "session ID")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return fmt.Errorf("failed to parse flags: %w", err)
	}
	return writeJSON(map[string]any{
		"command": "Open this project in Cursor to continue the session.",
	})
}

func cmdReadTranscript() error {
	fs := flag.NewFlagSet("read-transcript", flag.ContinueOnError)
	sessionRef := fs.String("session-ref", "", "session reference path")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return fmt.Errorf("failed to parse flags: %w", err)
	}
	data, err := os.ReadFile(*sessionRef) //nolint:gosec // path from agent hook input
	if err != nil {
		return fmt.Errorf("failed to read transcript: %w", err)
	}
	if _, err := os.Stdout.Write(data); err != nil {
		return fmt.Errorf("failed to write output: %w", err)
	}
	return nil
}

func cmdChunkTranscript() error {
	fs := flag.NewFlagSet("chunk-transcript", flag.ContinueOnError)
	maxSize := fs.Int("max-size", 0, "maximum chunk size in bytes")
	if err := fs.Parse(os.Args[2:]); err != nil {
		return fmt.Errorf("failed to parse flags: %w", err)
	}

	content, err := io.ReadAll(os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to read stdin: %w", err)
	}

	chunkSize := *maxSize
	if chunkSize <= 0 {
		chunkSize = len(content)
		if chunkSize == 0 {
			return writeJSON(map[string]any{"chunks": [][]byte{}})
		}
	}

	chunks, err := chunkJSONL(content, chunkSize)
	if err != nil {
		return fmt.Errorf("failed to chunk transcript: %w", err)
	}

	return writeJSON(map[string]any{"chunks": chunks})
}

func cmdReassembleTranscript() error {
	input, err := io.ReadAll(os.Stdin)
	if err != nil {
		return fmt.Errorf("failed to read stdin: %w", err)
	}

	var resp struct {
		Chunks [][]byte `json:"chunks"`
	}
	if err := json.Unmarshal(input, &resp); err != nil {
		return fmt.Errorf("failed to unmarshal chunks: %w", err)
	}

	result := reassembleJSONL(resp.Chunks)
	if _, err := os.Stdout.Write(result); err != nil {
		return fmt.Errorf("failed to write output: %w", err)
	}
	return nil
}

